func testTipoVeiculoToManyAddOpTPVCodigoNotaFiscalItemVeiculos(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a TipoVeiculo
	var b, c, d, e NotaFiscalItemVeiculo

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, tipoVeiculoDBTypes, false, strmangle.SetComplement(tipoVeiculoPrimaryKeyColumns, tipoVeiculoColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*NotaFiscalItemVeiculo{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, notaFiscalItemVeiculoDBTypes, false, strmangle.SetComplement(notaFiscalItemVeiculoPrimaryKeyColumns, notaFiscalItemVeiculoColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = c.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	foreignersSplitByInsertion := [][]*NotaFiscalItemVeiculo{
		{&b, &c},
		{&d, &e},
	}

	for i, x := range foreignersSplitByInsertion {
		err = a.AddTPVCodigoNotaFiscalItemVeiculos(ctx, tx, i != 0, x...)
		if err != nil {
			t.Fatal(err)
		}

		first := x[0]
		second := x[1]

		if a.TPVCodigo != first.TPVCodigo {
			t.Error("foreign key was wrong value", a.TPVCodigo, first.TPVCodigo)
		}
		if a.TPVCodigo != second.TPVCodigo {
			t.Error("foreign key was wrong value", a.TPVCodigo, second.TPVCodigo)
		}

		if first.R.TPVCodigoTipoVeiculo != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}
		if second.R.TPVCodigoTipoVeiculo != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}

		if a.R.TPVCodigoNotaFiscalItemVeiculos[i*2] != first {
			t.Error("relationship struct slice not set to correct value")
		}
		if a.R.TPVCodigoNotaFiscalItemVeiculos[i*2+1] != second {
			t.Error("relationship struct slice not set to correct value")
		}

		count, err := a.TPVCodigoNotaFiscalItemVeiculos().Count(ctx, tx)
		if err != nil {
			t.Fatal(err)
		}
		if want := int64((i + 1) * 2); count != want {
			t.Error("want", want, "got", count)
		}
	}
}

